// auth.js
import jwt from 'jsonwebtoken';

// Function to decode the token and get the payload
export const decodeToken = (token) => {
  if (!token) return null;

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET); // Use the same secret used for signing
    return decoded; // This will return the entire payload
  } catch (error) {
    console.error("❌ Token decoding error:", error);
    return null;
  }
};

// Function to get ownerId from the token
export const getOwnerIdFromToken = (token) => {
  const decoded = decodeToken(token);
  return decoded ? decoded.ownerId : null; // Assuming 'ownerId' is the key for owner ID in the token
};
